// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 30 ether);

        // First call at block.number = 1 (1%15 != 0), timestamp = 100
        vm.warp(100);
        vm.roll(1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call at block.number = 15 (15%15 == 0), timestamp = 200
        vm.warp(200);
        vm.roll(15);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // Third call at block.number = 2 (2%15 != 0), timestamp = 300
        vm.warp(300);
        vm.roll(2);
        (bool ok3,) = address(c).call{value: 10 ether}("");
        assertTrue(ok3);

        // In reference: only block 15 triggers transfer and sets pastBlockTime = 200
        // In bug: blocks 1 and 2 trigger transfer, last update is block 2 (timestamp 300)
        assertTrue(c.pastBlockTime() == 200);
    }
}
